const body = $input.first().json.body || $input.first().json;

const documentText = body.document_text || '';
const promptType = body.prompt_type || 'clinical_summary';
const documentId = body.document_id || 'doc_' + Date.now();
const customPrompt = body.custom_prompt || null;
const groundTruth = body.ground_truth_pii || null;

if (!documentText.trim()) {
  throw new Error('document_text is required and must not be empty');
}

// Normalize line endings using split/join (avoids CR characters in regex literals)
const normalizedText = documentText
  .split('\r\n').join('\n')
  .split('\r').join('\n')
  .trim();

// PII appears in the first part of medical documents (header section).
// Limit to 3000 chars so Ollama responds fast and does not time out.
const piiSection = normalizedText.slice(0, 3000);

// Build Ollama request body here in a Code node to safely handle special chars.
const ollamaBody = JSON.stringify({
  model: 'mistral',
  stream: false,
  options: { num_predict: 512, temperature: 0 },
  messages: [
    {
      role: 'system',
      content: 'You are a PII extraction specialist. Return ONLY a valid JSON array. No explanation, no markdown, just the array.'
    },
    {
      role: 'user',
      content: 'Extract all PII from the text below. Return ONLY a JSON array like:\n[{"entity":"Hans Mueller","type":"NAME"},{"entity":"14.03.1958","type":"DATE"}]\n\nTypes: NAME (patient and physician names), ADDRESS, DATE (all dates), ID_NUMBER (insurance/patient IDs).\n\nText:\n' + piiSection
    }
  ]
});

// Pre-build document store payload for 0b. Save Document node
const filename = body.filename || body.document_id || documentId;
const fileType = body.file_type || 'text';

const dbDocumentBody = JSON.stringify({
  document_id: documentId,
  filename: filename,
  file_type: fileType,
  raw_text: normalizedText,
  prompt_type: promptType,
  char_count: normalizedText.length
});


// Pre-build LangGraph request body
const langraphBody = JSON.stringify({
  document_id: documentId,
  document_text: normalizedText,
  prompt_type: promptType,
  pii_section: piiSection,
  custom_prompt: customPrompt,
  ground_truth: groundTruth
});

return [{
  json: {
    text: normalizedText,
    pii_section: piiSection,
    ollama_body: ollamaBody,
    db_document_body: dbDocumentBody,
    prompt_type: promptType,
    document_id: documentId,
    custom_prompt: customPrompt,
    ground_truth: groundTruth,
    char_count: normalizedText.length,
    langgraph_body: langraphBody
  }
}];

const input = $input.first().json;

const mappingSize = input.mapping_size
  || (input.mapping ? Object.keys(input.mapping).length : 0);

const response = {
  document_id: input.document_id,
  prompt_type: input.prompt_type,
  status: 'success',
  result: {
    analysis: input.restored_analysis,
    pii_entities_detected: mappingSize
  },
  evaluation: input.evaluation,
  privacy: {
    pii_sent_to_external_llm: false,
    pseudonyms_used: mappingSize,
    mapping_cleared_after_session: true
  }
};

return [{ json: response }];
